    }

    Dictionary<AddressAsKey, ChangeTrace>? trace = !stateTracer.IsTracingState ? null : [];

    ReadOnlySpan<Change> changes = CollectionsMarshal.AsSpan(_changes);
    for (int i = 0; i <= stepsBack; i++)
    {
