   342→    /// <summary>
   343→    /// Commit persistent storage trees
   344→    /// </summary>
   345→    /// <param name="blockNumber">Current block number</param>
   346→    public void CommitTrees(IBlockCommitter blockCommitter)
   347→    {
   348→        // Note: These all runs in about 0.4ms. So the little overhead like attempting to sort the tasks
   349→        // may make it worst. Always check on mainnet.
   350→
   351→        using ArrayPoolList<Task> commitTask = new ArrayPoolList<Task>(_storages.Count);
   352→        foreach (KeyValuePair<AddressAsKey, PerContractState> storage in _storages)
   353→        {
   354→            storage.Value.EnsureStorageTree(); // Cannot be called concurrently
   355→            if (blockCommitter.TryRequestConcurrencyQuota())
   356→            {
   357→                commitTask.Add(Task.Factory.StartNew((ctx) =>
   358→                {
   359→                    PerContractState st = (PerContractState)ctx;
   360→                    st.Commit();
   361→                    blockCommitter.ReturnConcurrencyQuota();
   362→                }, storage.Value));
   363→            }
   364→            else
   365→            {
   366→                storage.Value.Commit();
   367→            }
   368→        }
   369→
   370→        Task.WaitAll(commitTask.AsSpan());
   371→
   372→        _storages.Clear();
   373→    }
